/**
 * One toast for a finished "Process week": the pre-flight reason when the
 * bridge refused before any call, otherwise the week's counts.
 */
import type { AiCounts } from "./process-week-ai";
import type { UploadOutcome } from "./process-week-upload";
import type { ProcessWeekDeps } from "./use-process-week-deps";

export function reportProcessWeek(
  deps: ProcessWeekDeps,
  ai: AiCounts,
  upload: UploadOutcome
): void {
  const { toast, t } = deps;
  if ("blocked" in upload) {
    toast.error(t("toast.title"), t(`toast.preflight.${upload.blocked}`));
    return;
  }
  if (upload.total === 0) {
    toast.info(t("toast.title"), t("toast.reason.no-running"));
    return;
  }
  toast.success(
    t("toast.done"),
    t("toast.summary", {
      processed: ai.processed,
      pushed: upload.pushed,
      total: upload.total,
    })
  );
}
