import { useTranslate } from "../../../i18n/use-translate";
import { Icon, ICON_MAP } from "../../atoms/Icon";
import {
  ACTIVE_STROKE_WIDTH,
  INACTIVE_STROKE_WIDTH,
  TAB_ICON_SIZE,
} from "../../molecules/BottomNav/bottom-nav-styles";
import { useProcessWeekControls } from "./process-week-context";
import { processWeekProgress } from "./process-week-progress";

/** Mobile bottom-nav action: same tab metrics as a destination tab. */
export function ProcessWeekTabButton() {
  const { state, run } = useProcessWeekControls();
  const t = useTranslate("process-week");
  const label = processWeekProgress(state) ?? t("action");
  const running = state.stage !== "idle";
  return (
    <button
      type="button"
      onClick={run}
      disabled={running}
      aria-label={t("action")}
      data-testid="process-week-tab"
      className={`flex flex-1 flex-col items-center gap-1 py-2 ${
        running ? "text-accent" : "text-ink-muted"
      }`}
    >
      <Icon
        icon={ICON_MAP.zap}
        color="inherit"
        strokeWidth={running ? ACTIVE_STROKE_WIDTH : INACTIVE_STROKE_WIDTH}
        style={{ width: TAB_ICON_SIZE, height: TAB_ICON_SIZE }}
      />
      <span className="text-center text-[10.5px] leading-tight font-semibold">
        {label}
      </span>
    </button>
  );
}
