/**
 * "Process week" only touches running: the scheduled gym/strength days and
 * the coach's rest days stay out of both the AI batch and the Garmin push.
 * The family map already folds `run` / `trail_running` / `treadmill_running`
 * into `running`, so the predicate reads one canonical value.
 */
import type { WorkoutRecord } from "../../types/calendar-record";
import { canonicalSportFamily } from "../canonical-sport-family";

export const isRunningWorkout = (workout: WorkoutRecord): boolean =>
  canonicalSportFamily(workout.sport) === "running";
