/**
 * Stage "Process week"'s Garmin half: every running workout of the week that
 * has a KRD goes out through the same bulk "Send week" pipeline the calendar
 * uses (pre-flight, per-record lock, 500 ms cadence, continue on failure).
 * Non-running days never reach the bridge.
 */
import type { BulkPreflightFailure } from "../../../application/garmin-bulk/bulk-preflight";
import { isRunningWorkout } from "../../../application/garmin-bulk/is-running-workout";
import { selectWeekPushCandidates } from "../../../application/garmin-bulk/select-week-push-candidates";
import type { BulkOutcome } from "../../../application/garmin-bulk/send-week-to-garmin";
import { runSendWeek } from "../../../hooks/send-week/send-week-run";
import type { WeekRange } from "../../../utils/week-utils";
import type { SetProcessWeekState } from "./process-week-types";
import type { ProcessWeekDeps } from "./use-process-week-deps";

export type UploadOutcome =
  | { blocked: BulkPreflightFailure }
  | { pushed: number; failed: number; total: number };

export async function pushWeekToGarmin(
  deps: ProcessWeekDeps,
  range: WeekRange,
  setState: SetProcessWeekState
): Promise<UploadOutcome> {
  const runners = await readRunners(deps, range);
  if (runners.length === 0) return { pushed: 0, failed: 0, total: 0 };
  setState((state) => ({
    ...state,
    stage: "uploading",
    uploaded: 0,
    toUpload: runners.length,
  }));
  const run = await runSendWeek(
    sendContext(deps),
    selectWeekPushCandidates(runners),
    {
      isCancelled: () => false,
      onOutcome: () =>
        setState((state) => ({ ...state, uploaded: state.uploaded + 1 })),
    }
  );
  if (typeof run === "string") return { blocked: run };
  return countOutcomes(run.outcomes);
}

const readRunners = async (deps: ProcessWeekDeps, range: WeekRange) => {
  if (!deps.profileId) return [];
  const workouts = await deps.persistence.workouts.getByProfileAndDateRange(
    deps.profileId,
    range.start,
    range.end
  );
  return workouts.filter(isRunningWorkout);
};

const sendContext = (deps: ProcessWeekDeps) => ({
  persistence: deps.persistence,
  analytics: deps.analytics,
  features: deps.features,
  routeActive: deps.routeActive,
  bridgeInstalled: deps.extensionInstalled,
  sessionActive: deps.sessionActive,
});

const countOutcomes = (
  outcomes: readonly BulkOutcome[]
): Extract<UploadOutcome, { pushed: number }> => {
  let pushed = 0;
  let failed = 0;
  for (const outcome of outcomes) {
    if (
      outcome.status === "failed" ||
      outcome.status === "uncertain" ||
      outcome.status === "not-eligible"
    )
      failed++;
    else pushed++;
  }
  return { pushed, failed, total: outcomes.length };
};
