/**
 * One "Process week" run: the current ISO week's raw running workouts go
 * through the AI, then the whole week's running workouts are pushed to
 * Garmin. Gym and rest days are excluded from both stages. Nothing here
 * throws: a refusal is a translated toast and the button returns to idle.
 */
import { getCurrentWeekId, parseWeekId } from "../../../utils/week-utils";
import { processWeekWithAi } from "./process-week-ai";
import { prepareProcessWeek } from "./process-week-prepare";
import { reportProcessWeek } from "./process-week-report";
import type { SetProcessWeekState } from "./process-week-types";
import { pushWeekToGarmin } from "./process-week-upload";
import type { ProcessWeekDeps } from "./use-process-week-deps";

export async function runProcessWeek(
  deps: ProcessWeekDeps,
  setState: SetProcessWeekState
): Promise<void> {
  const range = parseWeekId(getCurrentWeekId());
  if (!range) return;
  const { toast, t } = deps;
  const prep = await prepareProcessWeek(deps.profileId, range.start, range.end);
  if (!prep.ok && prep.reason !== "no-running") {
    toast.error(t("toast.title"), t(`toast.reason.${prep.reason}`));
    return;
  }
  const ai = prep.ok
    ? await processWeekWithAi(deps, prep, setState)
    : { processed: 0, failed: 0 };
  const upload = await pushWeekToGarmin(deps, range, setState);
  reportProcessWeek(deps, ai, upload);
}
