import type { ProcessWeekState } from "./process-week-types";

/** "3/6" while a stage runs, `null` when idle. */
export const processWeekProgress = (state: ProcessWeekState): string | null => {
  if (state.stage === "processing")
    return `${state.processed}/${state.toProcess}`;
  if (state.stage === "uploading") return `${state.uploaded}/${state.toUpload}`;
  return null;
};
