/**
 * Stage "Process week"'s AI half: the shared batch runner over the week's raw
 * running workouts. Failure of one workout never stops the rest, and a row
 * that changed mid-call is reported skipped rather than counted as processed.
 */
import { processBatch } from "../../../application/batch-processor";
import { createProcessOne } from "../../pages/batch-process-one";
import type {
  ProcessWeekPrep,
  ProcessWeekState,
  SetProcessWeekState,
} from "./process-week-types";
import type { ProcessWeekDeps } from "./use-process-week-deps";

export type AiCounts = { processed: number; failed: number };

type Prepared = Extract<ProcessWeekPrep, { ok: true }>;

export async function processWeekWithAi(
  deps: ProcessWeekDeps,
  prep: Prepared,
  setState: SetProcessWeekState
): Promise<AiCounts> {
  setState(processingState(prep.workouts.length));
  const result = await processBatch(
    prep.workouts,
    createProcessOne(prep.provider, prep.modelId, deps.persistence),
    (progress) =>
      setState((state) => ({ ...state, processed: progress.processed })),
    new AbortController().signal
  );
  return { processed: result.succeeded.length, failed: result.failed.length };
}

const processingState = (total: number): ProcessWeekState => ({
  stage: "processing",
  processed: 0,
  toProcess: total,
  uploaded: 0,
  toUpload: 0,
});
