/**
 * The button's runtime state: one in-flight run at a time, progress while it
 * runs, back to idle when it settles (the result is reported by toast).
 */
import { useCallback, useRef, useState } from "react";

import { useLatestRef } from "../../../hooks/use-latest-ref";
import { IDLE_PROCESS_WEEK, type ProcessWeekState } from "./process-week-types";
import { runProcessWeek } from "./run-process-week";
import { useProcessWeekDeps } from "./use-process-week-deps";

export function useProcessWeek() {
  const depsRef = useLatestRef(useProcessWeekDeps());
  const [state, setState] = useState<ProcessWeekState>(IDLE_PROCESS_WEEK);
  const busy = useRef(false);

  const run = useCallback(async () => {
    if (busy.current) return;
    busy.current = true;
    const deps = depsRef.current;
    try {
      await runProcessWeek(deps, setState);
    } catch {
      const { toast, t } = deps;
      toast.error(t("toast.title"), t("toast.failed"));
    } finally {
      busy.current = false;
      setState(IDLE_PROCESS_WEEK);
    }
  }, [depsRef]);

  return { state, run };
}
