/**
 * Stage "Process week"'s AI half: the provider/model the week's batch needs
 * plus the raw *running* workouts only. Gym, strength and rest days are
 * skipped — they are not trainable runs and must not be sent to Garmin.
 */
import { isRunningWorkout } from "../../../application/garmin-bulk/is-running-workout";
import { prepareBatch } from "../../pages/batch-prepare";
import type { ProcessWeekPrep } from "./process-week-types";

export async function prepareProcessWeek(
  profileId: string | null,
  weekStart: string,
  weekEnd: string
): Promise<ProcessWeekPrep> {
  if (!profileId) return { ok: false, reason: "no-profile" };
  const prep = await prepareBatch(weekStart, weekEnd);
  if (!prep.ok) {
    return {
      ok: false,
      reason: prep.reason === "no-provider" ? "no-provider" : "no-running",
    };
  }
  const workouts = prep.workouts.filter(
    (workout) => workout.profileId === profileId && isRunningWorkout(workout)
  );
  if (workouts.length === 0) return { ok: false, reason: "no-running" };
  return { ok: true, provider: prep.provider, modelId: prep.modelId, workouts };
}
