/**
 * "Process week" is one button with two sequential stages: the AI turns every
 * raw running workout of the current week into a structured KRD, then the
 * whole week's running workouts go to Garmin. The state carries both stages'
 * counters so the button can show live progress.
 */
import type { Dispatch, SetStateAction } from "react";

import type { LlmProviderConfig } from "../../../store/ai-store-types";
import type { WorkoutRecord } from "../../../types/calendar-record";

export type ProcessWeekStage = "idle" | "processing" | "uploading";

export type ProcessWeekState = {
  stage: ProcessWeekStage;
  processed: number;
  toProcess: number;
  uploaded: number;
  toUpload: number;
};

export const IDLE_PROCESS_WEEK: ProcessWeekState = {
  stage: "idle",
  processed: 0,
  toProcess: 0,
  uploaded: 0,
  toUpload: 0,
};

export type ProcessWeekPrep =
  | {
      ok: true;
      provider: LlmProviderConfig;
      modelId: string;
      workouts: WorkoutRecord[];
    }
  | { ok: false; reason: "no-provider" | "no-profile" | "no-running" };

export type SetProcessWeekState = Dispatch<SetStateAction<ProcessWeekState>>;

export type RunProcessWeek = () => Promise<void>;
