/**
 * Everything the "Process week" run needs from the React tree, resolved once
 * in a hook so the orchestration stays a plain async function.
 */
import type { Analytics } from "@kaiord/core";

import { useAnalytics, useGarminBridge } from "../../../contexts";
import { usePersistence } from "../../../contexts/persistence-context";
import { useToastContext } from "../../../contexts/ToastContext";
import { useActiveProfileLive } from "../../../hooks/use-active-profile-live";
import { useGarminExportRoute } from "../../../hooks/use-garmin-export-route";
import { useTranslate } from "../../../i18n/use-translate";
import type { PersistencePort } from "../../../ports/persistence-port";

export type ProcessWeekDeps = {
  toast: ReturnType<typeof useToastContext>;
  t: ReturnType<typeof useTranslate>;
  persistence: PersistencePort;
  analytics: Analytics;
  features: readonly string[];
  extensionInstalled: boolean;
  sessionActive: boolean;
  routeActive: boolean;
  profileId: string | null;
};

export function useProcessWeekDeps(): ProcessWeekDeps {
  const toast = useToastContext();
  const t = useTranslate("process-week");
  const persistence = usePersistence();
  const analytics = useAnalytics();
  const { extensionInstalled, sessionActive, features } = useGarminBridge();
  const profileId = useActiveProfileLive()?.id ?? null;
  const routeActive = useGarminExportRoute(profileId) === true;
  return {
    toast,
    t,
    persistence,
    analytics,
    features,
    extensionInstalled,
    sessionActive,
    routeActive,
    profileId,
  };
}
