/**
 * The "Process week" action is rendered twice (header bar and mobile bottom
 * nav) but must run once. Both buttons read this context, so the in-flight
 * state and the busy guard are shared instead of duplicated per surface.
 *
 * Outside the provider the context answers an inert value: isolated stories
 * and component tests render the nav chrome without the whole app shell, and
 * an inert button is preferable to a crash there.
 */
import { createContext, useContext } from "react";

import {
  IDLE_PROCESS_WEEK,
  type ProcessWeekState,
  type RunProcessWeek,
} from "./process-week-types";

export type ProcessWeekControls = {
  state: ProcessWeekState;
  run: RunProcessWeek;
};

const INERT: ProcessWeekControls = {
  state: IDLE_PROCESS_WEEK,
  run: async () => {},
};

const ProcessWeekContext = createContext<ProcessWeekControls>(INERT);

export const ProcessWeekContextProvider = ProcessWeekContext.Provider;

export const useProcessWeekControls = (): ProcessWeekControls =>
  useContext(ProcessWeekContext);
