import { useTranslate } from "../../../i18n/use-translate";
import { Button } from "../../atoms/Button/Button";
import { Icon, ICON_MAP } from "../../atoms/Icon";
import { BAR_WRAPPER_CLASS } from "../../molecules/StatusHeader/header-menu-styles";
import { useProcessWeekControls } from "./process-week-context";
import { processWeekProgress } from "./process-week-progress";

/** Header-bar entry: the desktop twin of the bottom-nav action. */
export function ProcessWeekBarButton() {
  const { state, run } = useProcessWeekControls();
  const t = useTranslate("process-week");
  const running = state.stage !== "idle";
  return (
    <span className={BAR_WRAPPER_CLASS.desktop ?? undefined}>
      <Button
        size="sm"
        variant="secondary"
        onClick={run}
        disabled={running}
        loading={running}
        aria-label={t("action")}
        data-testid="process-week-button"
      >
        <Icon icon={ICON_MAP.zap} color="inherit" size="sm" />
        <span className="hidden md:inline">
          {processWeekProgress(state) ?? t("action")}
        </span>
      </Button>
    </span>
  );
}
