import type { ReactNode } from "react";

import {
  ProcessWeekContextProvider,
  type ProcessWeekControls,
} from "./process-week-context";
import { useProcessWeek } from "./use-process-week";

/** Mounts the single "Process week" run for the whole app shell. */
export function ProcessWeekProvider({ children }: { children: ReactNode }) {
  const { state, run } = useProcessWeek();
  const controls: ProcessWeekControls = { state, run };
  return (
    <ProcessWeekContextProvider value={controls}>
      {children}
    </ProcessWeekContextProvider>
  );
}
